      margin: 0.65rem 0 0;
      color: var(--secondary);
    }

    nav {
      display: flex;
      flex-wrap: wrap;
      gap: 1.25rem;
      margin-top: 1rem;
    }

    nav a {
      font-weight: 650;
    }

    .header-actions {
      display: flex;
      justify-content: flex-end;
      flex-shrink: 0;
    }

    #theme-toggle {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.65rem 0.85rem;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: var(--card);
      color: var(--text);
      font: inherit;
      cursor: pointer;
    }

    main {
      padding: 2.5rem 2rem;
    }

    section + section {
      margin-top: 3rem;
    }

    h2 {
      margin: 0 0 0.75rem;
      font-size: 1.75rem;
      line-height: 1.25;
    }

    .section-intro {
      max-width: 48rem;
      margin: 0 0 1.75rem;
      color: var(--secondary);
    }

    .member-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
      gap: 1.5rem;
    }

    .member-card {
      padding: 1.5rem;
      border: 1px solid transparent;
      border-radius: 1rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    [data-theme="dark"] .member-card {
      border-color: var(--border);
    }

    .member-card img {
      display: block;
      width: 8rem;
      height: 8rem;
      margin-bottom: 1rem;
      border-radius: 50%;
      object-fit: cover;
    }

    [data-theme="dark"] .member-card img {
      filter: brightness(0.9);
